#!/usr/bin/env python3
import json
import os
import sys

SYNC_DIR = "/workspace/memory/clawdbot-sync"
PEERS_FILE = os.path.join(SYNC_DIR, "peers.json")
HISTORY_FILE = os.path.join(SYNC_DIR, "history.json")

os.makedirs(SYNC_DIR, exist_ok=True)

def load_json(path, default):
    if os.path.exists(path):
        with open(path, 'r') as f:
            return json.load(f)
    return default

def save_json(path, data):
    with open(path, 'w') as f:
        json.dump(data, f, indent=2)

peers_data = load_json(PEERS_FILE, {"peers": [], "status": "pending"})

if len(sys.argv) < 2:
    cmd = "status"
else:
    cmd = sys.argv[1]

if cmd == "add":
    name = sys.argv[2]
    host = sys.argv[3]
    user = sys.argv[4] if len(sys.argv) > 4 else "clawdbot"
    path = sys.argv[5] if len(sys.argv) > 5 else os.getcwd()
    marker = f"SYNC_MARKER_{name.upper()}_001"

    # Check if peer exists
    found = False
    for peer in peers_data.get("peers", []):
        if peer["name"] == name:
            peer["host"] = host
            peer["user"] = user
            peer["path"] = path
            found = True
            break

    if not found:
        peers_data["peers"] = peers_data.get("peers", [])
        peers_data["peers"].append({
            "name": name,
            "host": host,
            "user": user,
            "path": path,
            "marker": marker
        })

    save_json(PEERS_FILE, peers_data)
    print(f"Added peer: {name} at {host}")

elif cmd in ["status", ""]:
    print("=== Clawdbot Sync Status ===")
    print("Peers configured:")
    for peer in peers_data.get("peers", []):
        print(f"  - {peer['name']}: {peer['host']} ({peer['user']}@{peer['path']})")
    if not peers_data.get("peers"):
        print("  No peers configured")
    print()
    print(f"Overall status: {peers_data.get('status', 'pending')}")
else:
    print("Usage: /sync [add|status|push|pull]")
    sys.exit(1)
EOF
